import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"13、【同人】 离下乾上","description":"横渠易说 - 13、【同人】 离下乾上","frontmatter":{"title":"13、【同人】 离下乾上","description":"横渠易说 - 13、【同人】 离下乾上"},"headers":[],"relativePath":"zh/classics/hengqu/015.md","filePath":"zh/classics/hengqu/015.md"}'),l={name:"zh/classics/hengqu/015.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_13、【同人】-离下乾上" tabindex="-1">13、【同人】 离下乾上 <a class="header-anchor" href="#_13、【同人】-离下乾上" aria-label="Permalink to “13、【同人】 离下乾上”">​</a></h1><h3 id="彖曰-同人-柔得位-得中而应乎乾曰同人。同人曰-同人于野亨-利涉大川-乾行也。文明以健-中正而应-君子正也。唯君子为能通天下之志。" tabindex="-1">彖曰：同人，柔得位，得中而应乎乾曰同人。同人曰“同人于野亨，利涉大川”，乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。 <a class="header-anchor" href="#彖曰-同人-柔得位-得中而应乎乾曰同人。同人曰-同人于野亨-利涉大川-乾行也。文明以健-中正而应-君子正也。唯君子为能通天下之志。" aria-label="Permalink to “彖曰：同人，柔得位，得中而应乎乾曰同人。同人曰“同人于野亨，利涉大川”，乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。”">​</a></h3><h3 id="象曰-天与火-同人-君子以类族辨物。" tabindex="-1">象曰：天与火，同人，君子以类族辨物。 <a class="header-anchor" href="#象曰-天与火-同人-君子以类族辨物。" aria-label="Permalink to “象曰：天与火，同人，君子以类族辨物。”">​</a></h3><p>不能与人同，未足为正也。 天下之心，天下之志，自是一物，天何常有如此间别!</p><h3 id="初九-同人于门-无咎。-象曰-出门同人-又谁咎也" tabindex="-1">初九，同人于门，无咎。 象曰：出门同人，又谁咎也! <a class="header-anchor" href="#初九-同人于门-无咎。-象曰-出门同人-又谁咎也" aria-label="Permalink to “初九，同人于门，无咎。 象曰：出门同人，又谁咎也!”">​</a></h3><h3 id="六二-同人于宗-吝。-象曰-同人于宗-吝道也。" tabindex="-1">六二，同人于宗，吝。 象曰：“同人于宗”，吝道也。 <a class="header-anchor" href="#六二-同人于宗-吝。-象曰-同人于宗-吝道也。" aria-label="Permalink to “六二，同人于宗，吝。 象曰：“同人于宗”，吝道也。”">​</a></h3><h3 id="九三-伏戎于莽-升其高陵-三岁不兴。-象曰-伏戎于莽-敌刚也。-三岁不兴-安行也。" tabindex="-1">九三，伏戎于莽，升其高陵，三岁不兴。 象曰：“伏戎于莽”，敌刚也。“三岁不兴”，安行也。 <a class="header-anchor" href="#九三-伏戎于莽-升其高陵-三岁不兴。-象曰-伏戎于莽-敌刚也。-三岁不兴-安行也。" aria-label="Permalink to “九三，伏戎于莽，升其高陵，三岁不兴。 象曰：“伏戎于莽”，敌刚也。“三岁不兴”，安行也。”">​</a></h3><h3 id="九四-乘其墉-弗克-攻-吉。-象曰-乘其墉-义弗克也。其吉则困而反则也。" tabindex="-1">九四，乘其墉，弗克，攻，吉。 象曰：“乘其墉”，义弗克也。其吉则困而反则也。 <a class="header-anchor" href="#九四-乘其墉-弗克-攻-吉。-象曰-乘其墉-义弗克也。其吉则困而反则也。" aria-label="Permalink to “九四，乘其墉，弗克，攻，吉。 象曰：“乘其墉”，义弗克也。其吉则困而反则也。”">​</a></h3><h3 id="九五-同人先号啕而后笑-大师克相遇。-象曰-同人之先-以中直也。大师相遇-言相克也。" tabindex="-1">九五，同人先号啕而后笑，大师克相遇。 象曰：同人之先，以中直也。大师相遇，言相克也。 <a class="header-anchor" href="#九五-同人先号啕而后笑-大师克相遇。-象曰-同人之先-以中直也。大师相遇-言相克也。" aria-label="Permalink to “九五，同人先号啕而后笑，大师克相遇。 象曰：同人之先，以中直也。大师相遇，言相克也。”">​</a></h3><h3 id="上九-同人于郊-无悔。-象曰-同人于郊-志未得也。" tabindex="-1">上九，同人于郊，无悔。 象曰：“同人于郊”，志未得也。 <a class="header-anchor" href="#上九-同人于郊-无悔。-象曰-同人于郊-志未得也。" aria-label="Permalink to “上九，同人于郊，无悔。 象曰：“同人于郊”，志未得也。”">​</a></h3><p>二与五应而为他间，己直人曲，望之必深，故号啕也。师直而壮，义同必克，故遇而后笑。</p>',11)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
